// ---- terrain3d: the real shape of the ground round a mark, from survey heights (see localDetail.js terrain) ----
// Where a place's hills matter (Whitby's East and West Cliffs), its ground's heights come from a survey instead of an
// estimate: a grid of heights round the mark, in the place's own metres (x east, z south of the mark), packed here in
// a base64 string (half-metre steps, one byte each; or with enc "dv16", centimetres, each row as changes from the last
// height, in zigzag varints). local.terrain names the grid; realPlace.js turns it into the hill function
// (metres above the land's usual level), as localDetail.js's hand-drawn hills are for Cromer and Gorleston.
//   step: metres between heights; n: heights a side; half: the grid runs from -half to +half in x and z;
//   floor: the survey height (metres above Ordnance Datum) that the land's usual level stands for: lower ground is
//   left flat, higher ground rises by the difference.

// (heights from the Environment Agency's LIDAR Composite DTM, 2022, 1 m, the bare ground, © Environment Agency, Open
// Government Licence v3.0; resampled to this grid by tools in the FishDock-assets workshop, 18 November 2026)
export const TERRAIN = {
  // Whitby's piers (whitby-piers): the survey's 1 m heights round the mark (British National Grid E 489200 to 490900,
  // N 510700 to 512400, fetched from the Environment Agency's WCS on 18 November 2026), every 5 m out to 640 m each way (beyond, the edge's heights carry on).
  // The harbour's quays and streets are about 3.5 m above Ordnance Datum: that is the land's usual level here; the East
  // Cliff rises to about 62 m at the Abbey, the West Cliff to about 30 m
  // (every 5 m, each height the mean of the survey's 1 m cells round it, in centimetres: at 8 m and in half-metre steps the
  // slopes came out terraced, the half-metre steps showing as stripes along the contours under a low sun)
  whitby: { step: 5, n: 257, half: 640, floor: 3.5, enc: "dv16",
    data: "" },
  // Cromer Pier (cromer-pier) and Brixham Breakwater (brixham-breakwater): the same survey (the Environment Agency's
  // LIDAR Composite DTM at 1 m, Open Government Licence, fetched from its WCS on 19 November 2026 for the 1.7 km square
  // round each mark), made into the same 5 m grid by source-assets/tools/terrain_from_dtm.py, each in a file of its own
  // so that only that place downloads it. floor: the land's usual level there (m above Ordnance Datum), read from the
  // survey: Cromer's promenade, 6.8 m (the town on the cliff is at 18 to 20 m, the cliffs to the west reach 39 m);
  // Brixham's breakwater, 5.8 m (the hills either side of the harbour reach 59 m)
  cromer: { step: 5, n: 257, half: 640, floor: 6.8, enc: "dv16", file: "terrain_cromer_5m.bin" },
  brixham: { step: 5, n: 257, half: 640, floor: 5.8, enc: "dv16", file: "terrain_brixham_5m.bin" },
  // Gorleston South Pier (gorleston-south-pier): the same survey and tool. floor: the quay and Pier Gardens, 3.6 m.
  // The cliff south of the pier's root rises 9 m in 30 m to Marine Parade at 13 to 16 m; the old town behind the quay
  // stands at 6 to 9 m; the spit north of the harbour mouth is at 5 to 6.5 m (it had been drawn as an 8 m dune, an
  // estimate from photographs)
  gorleston: { step: 5, n: 257, half: 640, floor: 3.6, enc: "dv16", file: "terrain_gorleston_5m.bin" },
};

const cache = new Map();
/** The hill function for a named grid: (x, z) => metres above the land's usual level (0 where the ground is low). */
// ---- the survey's own fine relief, where a place's ground is seen close to (realPlace.js lays it on a finer mesh) ----
// The 5 m terrain above is smooth: at Whitby the slope under St Mary's read as one green ramp. Here, over the East
// Cliff, the hillside and Henrietta Street, the same survey's 1 m heights minus the 5 m terrain's (its paths, walls,
// terraces, slips and gullies), in 2 cm steps, each row's first value then the changes as zigzag varints, in a file of
// its own (public/textures/<file>), fetched before the place is built so that only that place downloads it.
//   x0, z0: the first height's place (metres, as above); nx, nz: heights across and down, 1 m apart
export const RELIEF = {
  whitby: { file: "terrain_whitby_1m.bin", x0: -81, z0: 51, nx: 532, nz: 280, q: 0.02 },
  // (Cromer: the cliff behind the promenade either side of the pier, its paths, steps, terraces and retaining walls;
  // Brixham: the slope above the breakwater's root, towards Berry Head)
  cromer: { file: "terrain_cromer_1m.bin", x0: -402, z0: 99, nx: 703, nz: 280, q: 0.02 },
  brixham: { file: "terrain_brixham_1m.bin", x0: 150, z0: 201, nx: 451, nz: 400, q: 0.02 },
  // (Gorleston: the cliff, the Lower Esplanade at its foot and the old town behind the quay, west of the pier's root)
  gorleston: { file: "terrain_gorleston_1m.bin", x0: -600, z0: -120, nx: 301, nz: 601, q: 0.02 },
};
const reliefs = new Map();
/** Fetch and unpack a place's fine relief (a promise; null if it has none or it can't be had). */
export function loadRelief(name, base = "") {
  const R = RELIEF[name]; if (!R) return Promise.resolve(null);
  if (reliefs.has(name)) return Promise.resolve(reliefs.get(name));
  if (typeof fetch !== "function") return Promise.resolve(null);
  return fetch(base + R.file).then((r) => (r.ok ? r.arrayBuffer() : null)).then((buf) => {
    if (!buf) return null;
    const b = new Uint8Array(buf), D = new Float32Array(R.nx * R.nz); let p = 0;
    for (let j = 0; j < R.nz; j++) { let v = 0; for (let i = 0; i < R.nx; i++) { let z = 0, sh = 0, c; do { c = b[p++]; z += (c & 127) * 2 ** sh; sh += 7; } while (c & 128); v += z % 2 ? -(z + 1) / 2 : z / 2; D[j * R.nx + i] = v * R.q; } }
    const rel = { ...R, D };
    reliefs.set(name, rel); return rel;
  }).catch(() => null);
}
/** A place's fine relief if it has been fetched: { x0, z0, nx, nz, D (metres, row by row) }, else null. */
export function reliefOf(name) { return reliefs.get(name) || null; }
/** For the tests: unpack a relief from its bytes. */
export function setRelief(name, rel) { reliefs.set(name, rel); }

// ---- a place's 5 m grid kept in a file of its own (the environment system's places after Whitby) ----
// Inline, each place's grid (about 100 kB) would ride in every player's download; a place with file instead of data has
// its grid fetched before it is built (world.js preparePlace), the same dv16 bytes, raw. Made by
// source-assets/tools/terrain_from_dtm.py from the Environment Agency's survey.
const grids = new Map();
/** Fetch a place's 5 m grid if it lives in a file (a promise; resolves either way). */
export function loadTerrain(name, base = "") {
  const T = TERRAIN[name]; if (!T || T.data || grids.has(name) || typeof fetch !== "function") return Promise.resolve();
  return fetch(base + T.file).then((r) => (r.ok ? r.arrayBuffer() : null)).then((buf) => { if (buf) grids.set(name, new Uint8Array(buf)); }).catch(() => {});
}
/** For the tests: a place's grid from its bytes. */
export function setTerrainBytes(name, bytes) { grids.set(name, bytes); cache.delete(name); }

export function terrainHill(name) {
  if (cache.has(name)) return cache.get(name);
  const T = TERRAIN[name]; if (!T) return null;
  if (!T.data && !grids.has(name)) return null; // (its file not fetched: the place stands on its usual level)
  const raw = grids.get(name);
  const bin = raw ? { charCodeAt: (i) => raw[i] } : typeof atob === "function" ? atob(T.data) : Buffer.from(T.data, "base64").toString("binary");
  const H = new Float32Array(T.n * T.n);
  if (T.enc === "dv16") {
    // (centimetres, each row's first height then the change to the next, zigzag varints)
    let p = 0;
    for (let j = 0; j < T.n; j++) {
      let h = 0;
      for (let i = 0; i < T.n; i++) {
        let z = 0, sh = 0, b;
        do { b = bin.charCodeAt(p++); z += (b & 127) * 2 ** sh; sh += 7; } while (b & 128);
        h += z % 2 ? -(z + 1) / 2 : z / 2; H[j * T.n + i] = h / 100;
      }
    }
  } else for (let i = 0; i < H.length; i++) H[i] = bin.charCodeAt(i) * 0.5;
  // (Catmull-Rom across the grid, so the slopes are smooth between the survey's points, not faceted at every one)
  const at = (i, j) => H[Math.max(0, Math.min(T.n - 1, j)) * T.n + Math.max(0, Math.min(T.n - 1, i))];
  const cr = (p0, p1, p2, p3, t) => p1 + 0.5 * t * (p2 - p0 + t * (2 * p0 - 5 * p1 + 4 * p2 - p3 + t * (3 * (p1 - p2) + p3 - p0)));
  const f = (x, z) => {
    const u = Math.max(0, Math.min(T.n - 1.001, (x + T.half) / T.step)), v = Math.max(0, Math.min(T.n - 1.001, (z + T.half) / T.step));
    const i = Math.floor(u), j = Math.floor(v), a = u - i, b = v - j;
    const row = (jj) => cr(at(i - 1, jj), at(i, jj), at(i + 1, jj), at(i + 2, jj), a);
    const h = cr(row(j - 1), row(j), row(j + 1), row(j + 2), b);
    return Math.max(0, h - T.floor);
  };
  cache.set(name, f); return f;
}
